import { Component, ElementRef, Inject } from '@angular/core';
import { SettingService, SettingType } from 'espd-common/setting';
import { MODULE_NAME } from 'espd-common/config';

@Component({
    selector: 'espd-footer',
    template: '',
    standalone: false
})
export class FooterComponent  {
	constructor(@Inject(ElementRef) element: ElementRef, settingService: SettingService) {
		settingService.waitFor(MODULE_NAME).subscribe(() => {
			element.nativeElement.innerHTML = settingService.get(SettingType.CUSTOM_FOOTER) || '';
		});
	}
}